toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #04050A;
  font-family: "Orbitron, sans-serif";
}

>cyberCyan = #00F0FF;
>laserPink = #FF0055;
>deepVoid = #04050A;
>gridBorder = #141C2E;

circle #coreGlow {
  at: center of canvas offset 0px -40px;
  size: 260px;
  fill: alpha(>cyberCyan, 0.28);
}

rect #outerHexSquare {
  at: center of #coreGlow;
  size: 180px 180px;
  fill: none;
  stroke: >cyberCyan;
  stroke-width: 3px;
  rotation: 45deg;
}

rect #innerPinkFrame {
  at: center of #outerHexSquare;
  size: 110px 110px;
  fill: >deepVoid;
  stroke: >laserPink;
  stroke-width: 4px;
}

circle #dataNode {
  at: center of #innerPinkFrame;
  size: 28px;
  fill: >cyberCyan;
}

text #brandTitle {
  at: below #outerHexSquare offset 64px;
  content: "N E X U S _ 0 8";
  font-size: 28px;
  font-weight: 800;
  color: #FFFFFF;
}

text #brandProtocol {
  at: below #brandTitle offset 12px;
  content: "DECENTRALIZED COMPUTE FABRIC";
  font-size: 11px;
  font-weight: 600;
  color: >cyberCyan;
}
